select a.ma_ku, a.ma_kh, case when @@language = 'V' THEN b.ten_kh ELSE b.ten_kh2 END ten_kh, a.tien, a.thoi_han_vay, a.tg_an_han_goc
	from dmku a
		left join dmkh b on a.ma_kh = b.ma_kh
	where ma_ku = @0
exec zrpt_O044 null, null, @ma_ku, @ma_dvcs, '@@sysDatabaseName', @@language, @@userID, @@admin

			
		
	

	
		
			&OutlineEntry;
			&JavascriptReportFilter; 
			
function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete); 
	changeLookupReadonly(f, 'ma_dvcs');
}
function close$VoucherFilter$(f) {
	try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}
}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid, v = f.getItem('mau_bc').value; 
			g._hiddenForms = [];
			g._alterTitle = [null, [['%s1', f.getItemValue('ma_ku'), true], ['%s2', f.getItemValue('ten_ku%l'), true]]];
			//remove$GridReport$Filter(g);
			break;
		default:
			break;
	}
}

		
	

